import React, { useState } from 'react';

const Contact = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    subject: '',
    message: '',
  });

  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsSubmitted(true);
    setTimeout(() => {
      setIsSubmitted(false);
      setFormData({ name: '', email: '', subject: '', message: '' });
    }, 3000);
  };

  const contactLinks = [
    {
      label: 'Email',
      value: 'hello@bellezaa.com',
      href: 'mailto:hello@bellezaa.com',
    },
    {
      label: 'Location',
      value: 'New York, NY',
      href: '#',
    },
    {
      label: 'Availability',
      value: 'Open to projects',
      href: '#',
    },
  ];

  return (
    <div className="section" style={{ paddingTop: '140px' }}>
      <div className="container">
        {/* Header */}
        <div className="section-header">
          <p className="section-label">Contact</p>
          <h1>Let's Work Together</h1>
          <p className="section-description">
            Have a project in mind? I'd love to hear about it.
          </p>
        </div>

        <div className="contact-grid">
          {/* Contact Info */}
          <div className="contact-info">
            <h3>Get in Touch</h3>

            <p>
              I'm always interested in hearing about new projects and opportunities.
              Whether you have a question or just want to say hi, I'll do my best
              to get back to you within 24-48 hours.
            </p>

            <div className="contact-links">
              {contactLinks.map((link, index) => (
                <a key={index} href={link.href} className="contact-link">
                  <div className="contact-link-icon">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      {index === 0 && (
                        <>
                          <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/>
                          <polyline points="22,6 12,13 2,6"/>
                        </>
                      )}
                      {index === 1 && (
                        <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/>
                      )}
                      {index === 2 && (
                        <circle cx="12" cy="12" r="10"/>
                      )}
                    </svg>
                  </div>
                  <div className="contact-link-content">
                    <div className="contact-link-label">{link.label}</div>
                    <div className="contact-link-value">{link.value}</div>
                  </div>
                </a>
              ))}
            </div>

            {/* Response Time */}
            <div
              style={{
                marginTop: 'var(--space-10)',
                padding: 'var(--space-6)',
                background: 'var(--bg-secondary)',
                border: '1px solid var(--border-primary)',
                borderRadius: 'var(--radius-lg)',
              }}
            >
              <p
                className="text-mono"
                style={{ color: 'var(--text-muted)', marginBottom: 'var(--space-2)', fontSize: 'var(--text-xs)' }}
              >
                Typical Response Time
              </p>
              <p style={{ fontSize: 'var(--text-lg)', color: 'var(--text-primary)', margin: 0 }}>
                24-48 hours
              </p>
            </div>
          </div>

          {/* Contact Form */}
          <div className="contact-form">
            {isSubmitted ? (
              <div className="form-success">
                <div className="form-success-icon">✓</div>
                <h3 style={{ marginBottom: 'var(--space-3)' }}>
                  Message Sent!
                </h3>
                <p style={{ color: 'var(--text-secondary)', margin: 0 }}>
                  Thank you for reaching out. I'll get back to you soon.
                </p>
              </div>
            ) : (
              <form onSubmit={handleSubmit}>
                <div className="form-group">
                  <label htmlFor="name" className="form-label">
                    Name
                  </label>
                  <input
                    type="text"
                    id="name"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    className="form-input"
                    placeholder="Your name"
                    required
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="email" className="form-label">
                    Email
                  </label>
                  <input
                    type="email"
                    id="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    className="form-input"
                    placeholder="your@email.com"
                    required
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="subject" className="form-label">
                    Subject
                  </label>
                  <input
                    type="text"
                    id="subject"
                    name="subject"
                    value={formData.subject}
                    onChange={handleChange}
                    className="form-input"
                    placeholder="What's this about?"
                    required
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="message" className="form-label">
                    Message
                  </label>
                  <textarea
                    id="message"
                    name="message"
                    value={formData.message}
                    onChange={handleChange}
                    className="form-textarea"
                    placeholder="Tell me about your project..."
                    required
                  ></textarea>
                </div>

                <button type="submit" className="btn" style={{ width: '100%' }}>
                  <span>Send Message</span>
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Contact;
